import math

class Solution:
    def validSubarraySplit(self, nums: list[int]) -> int:
        n = len(nums)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0
        for i in range(n):
            if dp[i] == float('inf'):
                continue
            for j in range(i, n):
                if math.gcd(nums[i], nums[j]) > 1:
                    if dp[i] + 1 < dp[j + 1]:
                        dp[j + 1] = dp[i] + 1
        return dp[n] if dp[n] != float('inf') else -1

class Solution {
public:
    int validSubarraySplit(std::vector<int>& nums) {
        int n = nums.size();
        const int INF = 1e9;
        std::vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < n; ++i) {
            if (dp[i] == INF) continue;
            for (int j = i; j < n; ++j) {
                if (std::gcd(nums[i], nums[j]) > 1) {
                    dp[j + 1] = std::min(dp[j + 1], dp[i] + 1);
                }
            }
        }
        return dp[n] == INF ? -1 : dp[n];
    }
};

class Solution {
    public int validSubarraySplit(int[] nums) {
        int n = nums.length;
        int INF = (int) 1e9;
        int[] dp = new int[n + 1];
        java.util.Arrays.fill(dp, INF);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == INF) continue;
            for (int j = i; j < n; j++) {
                if (gcd(nums[i], nums[j]) > 1) {
                    dp[j + 1] = Math.min(dp[j + 1], dp[i] + 1);
                }
            }
        }
        return dp[n] == INF ? -1 : dp[n];
    }
    private int gcd(int a, int b) {
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

